	private List<BindingSet> rowsWithBatchRows(String query, Mode mode, int batchRows) {
		set(NativeBatch.ROWS_PROPERTY, Integer.toString(batchRows));
		set(NativeBatch.ENABLED_PROPERTY, "true");
		return rows(query, mode);
	}

	@Test
	void actualRdfModelKeyingCannotTouchDictionary() {
		NativeLmdbQuerySource forbidden = (NativeLmdbQuerySource) Proxy.newProxyInstance(
				NativeLmdbQuerySource.class.getClassLoader(), new Class<?>[] { NativeLmdbQuerySource.class },
				(proxy, method, args) -> {
					if (method.getName().equals("hasCanonicalIds")) {
						return true;
					}
					throw new AssertionError("Unexpected dictionary operation during generated keying: " + method);
				});
		var valueFactory = SimpleValueFactory.getInstance();
		try (var context = new NativeExecutionContext();
				var keys = new NativeGeneratedKeyAuthority(
						new LmdbNativeTermAuthority(forbidden, PlanValueCatalog.EMPTY, context), context)) {
			Value[] values = { valueFactory.createLiteral("Aa"), valueFactory.createLiteral("BB"),
					valueFactory.createLiteral("x", "EN"), valueFactory.createLiteral("x", "en"),
					valueFactory.createLiteral("x", "en", Literal.BaseDirection.LTR),
					valueFactory.createLiteral("x", "en", Literal.BaseDirection.RTL),
					valueFactory.createIRI(EX, "x") };
			long[] ids = new long[values.length];
			for (int i = 0; i < ids.length; i++) {
				ids[i] = keys.intern(values[i]);
			}
			for (int i = 0; i < ids.length; i++) {
				for (int j = 0; j < ids.length; j++) {
					assertEquals(values[i].equals(values[j]), keys.sameRdfTerm(ids[i], ids[j]));
				}
			}
			for (int i = 0; i < ids.length; i++) {
				assertEquals(values[i], keys.valueOf(ids[i]));
				if (values[i]instanceof Literal original) {
					Literal materialized = (Literal) keys.valueOf(ids[i]);
					assertEquals(original.getLanguage(), materialized.getLanguage());
					assertEquals(original.getBaseDirection(), materialized.getBaseDirection());
				}
			}
		}
	}

	@Test
	void compactStringIngressAgreesWithTheActualModel() {
		NativeLmdbQuerySource forbidden = (NativeLmdbQuerySource) Proxy.newProxyInstance(
				NativeLmdbQuerySource.class.getClassLoader(), new Class<?>[] { NativeLmdbQuerySource.class },
				(proxy, method, args) -> {
					if (method.getName().equals("hasCanonicalIds")) {
						return true;
					}
					throw new AssertionError("Unexpected dictionary operation: " + method);
				});
		var valueFactory = SimpleValueFactory.getInstance();
		try (var context = new NativeExecutionContext();
				var keys = new NativeGeneratedKeyAuthority(
						new LmdbNativeTermAuthority(forbidden, PlanValueCatalog.EMPTY, context), context)) {
			for (String label : List.of("", "Aa", "BB", "a generated string", "\u03bb\ud83d\ude00", "\u0000")) {
				long original = keys.internString(label);
				assertEquals(original, keys.intern(valueFactory.createLiteral(label)));
				assertEquals(valueFactory.createLiteral(label), keys.valueOf(original));
				assertTrue(context.isUnresolvedKey(original));
				assertEquals(original, keys.canonicalTermKey(original));
			}
			long upper = keys.intern(valueFactory.createLiteral("original spelling", "EN"));
			long lower = keys.intern(valueFactory.createLiteral("original spelling", "en"));
			assertEquals(keys.canonicalTermKey(upper), keys.canonicalTermKey(lower));
			assertEquals("EN", ((Literal) keys.valueOf(upper)).getLanguage().orElseThrow());
			assertEquals("en", ((Literal) keys.valueOf(lower)).getLanguage().orElseThrow());
			assertTrue(LmdbNativeValueCodec.fromValue(valueFactory.createLiteral("text")).plainStringLiteral());
			assertFalse(LmdbNativeValueCodec.fromValue(valueFactory.createLiteral("text", "en")).plainStringLiteral());
			assertFalse(LmdbNativeValueCodec.fromValue(
					valueFactory.createLiteral("text", "en", Literal.BaseDirection.RTL)).plainStringLiteral());
			assertFalse(LmdbNativeValueCodec.fromValue(valueFactory.createLiteral(42)).plainStringLiteral());
			assertFalse(LmdbNativeValueCodec.fromValue(valueFactory.createIRI(EX, "iri")).plainStringLiteral());
		}
	}

	@Test
	void generatedKeysFeedAnActualSpillingGroupStoreWithoutDictionaryLookups() {
		NativeLmdbQuerySource dictionaryFree = dictionaryFreeSource();
		var valueFactory = SimpleValueFactory.getInstance();
		set(NativeRuntimeValueTable.MAX_BYTES_PROPERTY, Long.toString(16L << 20));
		LmdbQueryMemoryManager memory = LmdbQueryMemoryManager.createForTesting(16L << 20, 16L << 20);
		int entries = 2100;
		int uniqueValues = 700;
		Map<Value, Long> expected = new LinkedHashMap<>();
		try (var context = new NativeExecutionContext();
				var keys = new NativeGeneratedKeyAuthority(
						new LmdbNativeTermAuthority(dictionaryFree, PlanValueCatalog.EMPTY, context), context);
				var ledger = memory.openQuery();
				var store = new NativeCountGroupStore(1, new boolean[] { false }, keys::canonicalTermKey, null, ledger,
						4096)) {
			for (int i = 0; i < entries; i++) {
				Value value = valueFactory.createLiteral("spill-generated-key-" + i % uniqueValues);
				long id = keys.intern(value);
				expected.merge(value, 1L, Long::sum);
				store.add(new long[] { id }, new long[] { id }, 1);
			}
			assertTrue(context.runtimeValueAccountedBytes() > 0,
					"generated terms were not retained by the evaluation context");
			assertTrue(store.spilledRecords() > 0, "generated-key grouping did not exercise the spill path");
			store.finish();
			long[] row = new long[2];
			Map<Value, Long> actual = new LinkedHashMap<>();
			while (store.next(row)) {
				Value value = keys.valueOf(row[0]);
				assertTrue(value != null, "spilled generated-key representative could not be materialized");
				assertFalse(actual.containsKey(value), "spilled group was emitted more than once: " + value);
				actual.put(value, row[1]);
			}
			assertEquals(expected, actual,
					"spilled generated-key groups must preserve exact RDF representatives and counts");
		}
		assertEquals(0L, memory.usedBytes(), "spilling group state leaked its query reservation");
	}

	@Test
	void generatedKeySpillCancellationClosesTheStoreAndEvaluationState() {
		NativeLmdbQuerySource dictionaryFree = dictionaryFreeSource();
		var valueFactory = SimpleValueFactory.getInstance();
		set(NativeRuntimeValueTable.MAX_BYTES_PROPERTY, Long.toString(16L << 20));
		LmdbQueryMemoryManager memory = LmdbQueryMemoryManager.createForTesting(16L << 20, 16L << 20);
		KernelCancellation cancellation = new KernelCancellation(Long.MAX_VALUE);
		NativeExecutionContext context = new NativeExecutionContext();
		NativeGeneratedKeyAuthority keys = new NativeGeneratedKeyAuthority(
				new LmdbNativeTermAuthority(dictionaryFree, PlanValueCatalog.EMPTY, context), context);
		try {
			try (var ledger = memory.openQuery();
					var store = new NativeCountGroupStore(1, new boolean[] { true }, keys::canonicalTermKey,
							cancellation,
							ledger, 4096)) {
				for (int i = 0; i < 1200; i++) {
					long id = keys.intern(valueFactory.createLiteral("cancel-generated-key-" + i));
					store.add(new long[] { id }, new long[] { id }, 1);
				}
				assertTrue(store.spilledRecords() > 0, "cancellation test must own a spill before cancellation");
				assertTrue(context.runtimeValueAccountedBytes() > 0,
						"generated terms were not retained before cancellation");
				long id = keys.intern(valueFactory.createLiteral("cancel-after-input"));
				cancellation.cancel();
				assertThrows(KernelCancelledException.class,
						() -> store.add(new long[] { id }, new long[] { id }, 1));
			}
		} finally {
			keys.close();
			context.close();
		}
		assertTrue(context.isClosed(), "evaluation context remained open after cancellation cleanup");
		assertEquals(0L, context.runtimeValueAccountedBytes(), "generated-value payload survived context close");
		assertEquals(0L, memory.usedBytes(), "cancelled generated-key spill state leaked its reservation");
	}

	@Test
	void generatedKeyQueriesRemainIndependentAcrossConcurrentEvaluations() throws Exception {
		String query = "SELECT DISTINCT ?k WHERE { ?s ex:label ?v BIND(LCASE(?v) AS ?k) }";
		Map<BindingSet, Long> expected = bag(rows(query, Mode.GENERIC));
		configure(Mode.LOCAL_NATIVE);
		long before = NativeGeneratedKeyPlan.ACTIVATIONS.get();
		int workers = 4;
		ExecutorService pool = Executors.newFixedThreadPool(workers);
		CountDownLatch ready = new CountDownLatch(workers);
		CountDownLatch start = new CountDownLatch(1);
		List<Future<Map<BindingSet, Long>>> futures = new ArrayList<>();
		try {
			for (int i = 0; i < workers; i++) {
				futures.add(pool.submit(() -> {
					ready.countDown();
					start.await();
					return bag(rowsWithCurrentConfiguration(query));
				}));
			}
			assertTrue(ready.await(30, TimeUnit.SECONDS), "concurrent generated-key workers did not become ready");
			start.countDown();
			for (Future<Map<BindingSet, Long>> future : futures) {
				assertEquals(expected, future.get(30, TimeUnit.SECONDS));
			}
		} finally {
			pool.shutdownNow();
			assertTrue(pool.awaitTermination(30, TimeUnit.SECONDS),
					"concurrent generated-key workers remained alive during repository cleanup");
		}
		assertTrue(NativeGeneratedKeyPlan.ACTIVATIONS.get() > before,
				"concurrent local-native evaluations did not activate generated-key execution");
	}

	@Test
	void runtimeAdmissionFailureMustNotBeFoldedIntoAnUnboundKey() {
		set(NativeRuntimeValueTable.MAX_BYTES_PROPERTY, "4096");
		assertThrows(QueryEvaluationException.class,
				() -> rows("SELECT ?k (COUNT(*) AS ?c) WHERE { ?s ex:label ?v BIND(LCASE(?v) AS ?k) } GROUP BY ?k",
						Mode.LOCAL_NATIVE),
				"Resource refusal must fail the evaluation, not drop keys or return partial groups");
	}
